// ST GAMES: THE PARADISE - Studio Audio & Auto-Play Manager
// Ready for subdirectory hosting (e.g. https://stgames.online/game/tfi/)
class ParadiseAudioManager {
  constructor() {
    this.soundOn = true;
    this.musicVolume = 0.22; // Soft background music so dialogues stand out
    this.sfxVolume = 0.98;   // Clear dialogues, shouts, level-clear & gameover songs
    this.ctx = null;
    this.hasStartedOnce = false;
    this.passCount = 0;

    this.paths = {
      startDialogue: './assets/audio/start-dialogue.mp3',
      dialogue: './assets/audio/character-dialogue.mp3',
      bgm: './assets/audio/paradise-bgm.mp3',
      levelClear: './assets/audio/level-clear.mp3',
      gameover: './assets/audio/gameover.mp3',
      dangerAlert: './assets/audio/danger-alert.mp3',
      policeComing: './assets/audio/police-coming.mp3',
      eeDesham: './assets/audio/ee-desham-manadhe.mp3',
      eeJaaga: './assets/audio/ee-jaaga-manadhe.mp3',
      pass: './assets/audio/pass.mp3',
      passDialogue: './assets/audio/pass-dialogue.mp3',
      footsteps: './assets/audio/footsteps.mp3',
      dog: './assets/audio/dog.mp3',
      birds: './assets/audio/birds.mp3'
    };

    this.embeddedAudio = {"bgm": "data:audio/mp3;base64,", "levelClear": "data:audio/mp3;base64,", "startDialogue": "data:audio/mp3;base64,", "gameover": "data:audio/mp3;base64,", "eeDesham": "data:audio/mp3;base64,", "eeJaaga": "data:audio/mp3;base64,", "dangerAlert": "data:audio/mp3;base64,"};
    this.elements = {};
    this.setupAutoPlayUnlock();
  }

  // Automatically start songs on page load, and if mobile browser blocks autoplay until first touch, start immediately on first touch!
  setupAutoPlayUnlock() {
    const unlock = () => {
      if (!this.soundOn) return;
      if (!this.ctx) {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (AudioCtx) this.ctx = new AudioCtx();
      }
      if (this.ctx && this.ctx.state === 'suspended') {
        this.ctx.resume().catch(() => {});
      }
      if (!this.hasStartedOnce) {
        this.hasStartedOnce = true;
        this.playLevelStartAudio();
      } else if (this.elements.bgm && this.elements.bgm.paused && window.paradiseGame && !window.paradiseGame.gameOver && !window.paradiseGame.levelWon && !window.paradiseGame.paused) {
        this.elements.bgm.play().catch(() => {});
      }
    };

    ['pointerdown', 'touchstart', 'mousedown', 'keydown', 'click'].forEach((evt) => {
      window.addEventListener(evt, unlock, { passive: true });
    });
  }

  tryAutoStart() {
    if (!this.soundOn) return;
    this.initContext();
    this.playLevelStartAudio();
  }

  initContext() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) this.ctx = new AudioCtx();
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
  }

  toggleSound() {
    this.soundOn = !this.soundOn;
    if (this.soundOn) {
      this.hasStartedOnce = true;
      this.initContext();
      this.startBGM();
    } else {
      this.stopAllAudio();
    }
    return this.soundOn;
  }

  setVolumes(musicVol, sfxVol) {
    this.musicVolume = Math.max(0, Math.min(1, musicVol));
    this.sfxVolume = Math.max(0, Math.min(1, sfxVol));
    if (this.elements.bgm) {
      this.elements.bgm.volume = this.musicVolume;
    }
  }

  stopAllAudio() {
    Object.values(this.elements).forEach((el) => {
      try {
        el.pause();
        el.currentTime = 0;
      } catch (e) {}
    });
  }

  playTrack(key, isLoop, volScale, fallbackToneFn) {
    if (!this.soundOn) return;
    const fileUrl = this.paths && this.paths[key];
    const dataUri = this.embeddedAudio && this.embeddedAudio[key];
    const useDataUri = !fileUrl || fileUrl.startsWith('https://stgames.online/');
    const primarySrc = useDataUri ? dataUri : fileUrl;

    if (!primarySrc) {
      if (fallbackToneFn) fallbackToneFn();
      return;
    }

    try {
      let el = this.elements[key];
      if (!el) {
        el = new Audio(primarySrc);
        this.elements[key] = el;
      }
      el.loop = !!isLoop;
      el.volume = Math.max(0, Math.min(1, volScale));
      el.currentTime = 0;
      const p = el.play();
      if (p && typeof p.then === 'function') {
        p.then(() => {
          this.hasStartedOnce = true;
        }).catch(() => {
          if (!useDataUri && dataUri) {
            el.src = dataUri;
            el.volume = Math.max(0, Math.min(1, volScale));
            el.play().then(() => {
              this.hasStartedOnce = true;
            }).catch(() => {
              if (fallbackToneFn) fallbackToneFn();
            });
          } else if (fallbackToneFn) {
            fallbackToneFn();
          }
        });
      }
    } catch (e) {
      if (fallbackToneFn) fallbackToneFn();
    }
  }

  playLevelStartAudio() {
    if (!this.soundOn) return;
    this.stopAllAudio();
    this.playTrack('startDialogue', false, this.sfxVolume);
    this.startBGM();
  }

  startBGM() {
    if (!this.soundOn) return;
    this.playTrack('bgm', true, this.musicVolume);
  }

  playTone(freq, duration, type = 'sine', vol = 0.14) {
    if (!this.soundOn) return;
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) this.ctx = new AudioCtx();
    }
    if (!this.ctx) return;
    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, now);
      gain.gain.setValueAtTime(vol * this.sfxVolume, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(now);
      osc.stop(now + duration + 0.02);
    } catch (e) {}
  }

  playPass(receiverId) {
    if (!this.soundOn) return;
    this.passCount++;
    const trackKey = this.passCount % 2 === 1 ? 'eeDesham' : 'eeJaaga';
    this.playTrack(trackKey, false, this.sfxVolume);

    if (receiverId === 'dog') {
      setTimeout(() => this.playDogBark(), 160);
    } else if (receiverId === 'crow') {
      setTimeout(() => this.playCrowCaw(), 160);
    }
  }

  playTooFar() {
    this.playTone(170, 0.18, 'sawtooth', 0.18);
    setTimeout(() => this.playTone(135, 0.20, 'sawtooth', 0.18), 90);
  }

  playDanger(isFirstWave = true) {
    if (!this.soundOn) return;
    if (isFirstWave) {
      this.playTrack('dangerAlert', false, this.sfxVolume);
    }
    this.playPoliceSiren();
  }

  playTowerAlert() {
    if (!this.soundOn) return;
    [0, 180, 360].forEach((delay) => {
      setTimeout(() => {
        this.playTone(940, 0.12, 'square', 0.20);
        setTimeout(() => this.playTone(720, 0.10, 'sawtooth', 0.18), 70);
      }, delay);
    });
  }

  playGunshot() {
    if (!this.soundOn) return;
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) this.ctx = new AudioCtx();
    }
    if (!this.ctx) return;
    try {
      const now = this.ctx.currentTime;
      const bufferSize = this.ctx.sampleRate * 0.28;
      const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (this.ctx.sampleRate * 0.06));
      }
      const noise = this.ctx.createBufferSource();
      noise.buffer = buffer;
      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(0.42 * this.sfxVolume, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.26);
      noise.connect(gain);
      gain.connect(this.ctx.destination);
      noise.start(now);
      this.playTone(110, 0.22, 'sawtooth', 0.28);
    } catch (e) {}
  }

  playPoliceSiren() {
    if (!this.soundOn) return;
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) this.ctx = new AudioCtx();
    }
    if (!this.ctx) return;
    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(580, now);
      osc.frequency.linearRampToValueAtTime(860, now + 0.18);
      osc.frequency.linearRampToValueAtTime(560, now + 0.36);
      osc.frequency.linearRampToValueAtTime(880, now + 0.54);
      gain.gain.setValueAtTime(0.14 * this.sfxVolume, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.60);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(now);
      osc.stop(now + 0.62);
    } catch (e) {}
  }

  playProximityAlert() {
    this.playTone(820, 0.08, 'square', 0.12);
    setTimeout(() => this.playTone(620, 0.10, 'square', 0.12), 90);
  }

  playGameOver() {
    this.stopAllAudio();
    this.playTrack('gameover', false, this.sfxVolume, () => {
      this.playTone(220, 0.25, 'sawtooth', 0.2);
    });
  }

  playLevelClear() {
    this.stopAllAudio();
    this.playTrack('levelClear', false, this.sfxVolume, () => {
      this.playTone(554.37, 0.25, 'triangle', 0.22);
    });
  }

  playDogBark() {
    this.playTone(340, 0.08, 'sawtooth', 0.18);
    setTimeout(() => this.playTone(260, 0.11, 'sawtooth', 0.18), 85);
  }

  playCrowCaw() {
    this.playTone(620, 0.11, 'sawtooth', 0.16);
    setTimeout(() => this.playTone(540, 0.13, 'sawtooth', 0.16), 95);
  }
}

window.paradiseAudio = new ParadiseAudioManager();
